import sys,math,numpy as np
from PIL import Image,ImageDraw
sys.path.insert(0,'/app/output');import gen
G=gen.glyph_routes();tar=np.array(Image.open('/app/target.png').convert('L'))<128
for deg in [20,25,30,35,40,45]:
 canvas=Image.new('1',(1024,1024));dr=ImageDraw.Draw(canvas)
 for g in G:
  for st in g['strokes']:
   p=st['route'];d=np.gradient(p,axis=0);phi=np.arctan2(-d[:,1],-d[:,0]); w=np.clip(18.04*np.abs(np.cos(math.radians(deg)-phi)),1.8,18.04)
   for j in range(len(p)-1):
    width=max(1,int(round((w[j]+w[j+1])/2)))
    dr.line([(p[j,1],p[j,0]),(p[j+1,1],p[j+1,0])],fill=1,width=width)
 pred=np.array(canvas)>0
 best=(0,None)
 for dy in range(-22,23):
  for dx in range(-22,23):
   a=np.roll(np.roll(pred,dy,0),dx,1);iou=(a&tar).sum()/(a|tar).sum()
   if iou>best[0]:best=(iou,(dx,dy))
 print(deg,'area',pred.sum(),'iou',round(best[0],3),'shift',best[1],'target',tar.sum())
